import{_ as i}from"./plugin-vue_export-helper-c27b6911.js";import{r as l,o as e,c as s,a as p,d as t,e as n,b as o}from"./app-3576880b.js";const d={},g={href:"https://www.wizard101central.com/wiki/Item:Splendid_Chapeau",target:"_blank",rel:"noopener noreferrer"},u={href:"https://www.wizard101central.com/wiki/Item:Splendid_Tunic",target:"_blank",rel:"noopener noreferrer"},h={href:"https://www.wizard101central.com/wiki/Item:Splendid_Boots",target:"_blank",rel:"noopener noreferrer"},m={href:"https://www.wizard101central.com/wiki/Item:Greenwarden%27s_Energetic_Mask_(Level_90%2B)",target:"_blank",rel:"noopener noreferrer"},b={href:"https://www.wizard101central.com/wiki/Item:Greenwarden%27s_Energetic_Shroud_(Level_90%2B)",target:"_blank",rel:"noopener noreferrer"},w={href:"https://www.wizard101central.com/wiki/Item:Greenwarden%27s_Energetic_Boots_(Level_90%2B)",target:"_blank",rel:"noopener noreferrer"},f={href:"https://www.wizard101central.com/wiki/House:Pink_Dandelion",target:"_blank",rel:"noopener noreferrer"},c={href:"https://wiki.wizard101central.com/wiki/House:Yellow_Bell_Pepper",target:"_blank",rel:"noopener noreferrer"},k={href:"https://www.wizard101central.com/wiki/House:King_Parsley",target:"_blank",rel:"noopener noreferrer"},y={href:"https://www.wizard101central.com/wiki/House:Couch_Potatoes",target:"_blank",rel:"noopener noreferrer"},z={href:"https://www.bilibili.com/video/BV1xX4y1m7gB/?spm_id_from=333.337.search-card.all.click",target:"_blank",rel:"noopener noreferrer"};function x(G,a){const r=l("ExternalLinkIcon");return e(),s("div",null,[a[33]||(a[33]=p('<p><br><mark>园艺在是相当重要的宠物小吃、珍惜宝藏卡、各类珍惜材料的来源。在你能够实现材料或小吃自由之前，需要大量的能量和时间投入。<br> 本篇文章将会介绍新手如何从0开始园艺并逐渐成为Gardening Warlord!</mark></p><h2 id="基础知识" tabindex="-1"><a class="header-anchor" href="#基础知识" aria-hidden="true">#</a> <mark>基础知识</mark></h2><p>首先，玩家需要在达到12级时接取第一个园艺任务。<br> 具体地址在拉文霍德（Ravenwood）-生命系学院（Life School）-穆林达（Moolinda）处接取。<br> 该任务将会带你去认识一个新NPC Farley，它将指导玩家如何开始园艺以及种植和照料作物。<br> 植物种植可以在宿舍或者城堡进行，皇冠商城的红谷仓农场有额外种植加成，推荐第一个购买。</p><figure><img src="https://subata.top/wp-content/uploads/2023/07/I2F@MQQJ79AQ1U8FE-1.png" alt="打开商城找到家具" tabindex="0" loading="lazy"><figcaption>打开商城找到家具</figcaption></figure><figure><img src="https://subata.top/wp-content/uploads/2023/07/ZG4QYKSH7@YAVSBMJA-1.png" alt="找到红谷仓农场" tabindex="0" loading="lazy"><figcaption>找到红谷仓农场</figcaption></figure><figure><img src="https://subata.top/wp-content/uploads/2023/07/ZZO09X8D5_M47F6PP50@5R.png" alt="点击金币,即可用金币购买" tabindex="0" loading="lazy"><figcaption>点击金币,即可用金币购买</figcaption></figure><p><mark>↑以上为购买步骤，不要傻傻用皇冠买了</mark></p><figure><img src="https://subata.top/wp-content/uploads/2023/07/Photo-Houses-2020-05-30-07-22-03-768x432-1.jpg" alt="家园展示" tabindex="0" loading="lazy"><figcaption>家园展示</figcaption></figure><h2 id="能量消耗" tabindex="-1"><a class="header-anchor" href="#能量消耗" aria-hidden="true">#</a> <mark>能量消耗</mark></h2><p>能量是园艺的一个重要部分。玩家可以通过观察左下角旁边的黄色水晶条来了解你有多少能量。每当玩家使用园艺魔法，能量会被消耗。升级可以补充能量，也可以从皇冠商店花250皇冠购买能量药水来恢复。</p><p>基础能量大体上与等级相关，最高级为130能量。一些装备会增加玩家的最大能量上限，具体可以参考隔壁常驻卡包攻略了解卡包能量装的加成。此外，进行伐木darkmoor tier3外的石头钥匙Boss食人花，也可以获得武器戒指匕首三件套能量装。其中DM3石头钥匙Boss掉落的戒指和匕首是目前能量加的最多的饰品。</p><p>无皇冠幣且不算家园结界可以去打札佛的镜湖，有splendid套装，可以+45能量上限。</p><h1 id="辉煌套" tabindex="-1"><a class="header-anchor" href="#辉煌套" aria-hidden="true">#</a> 辉煌套</h1>',13)),t("ul",null,[t("li",null,[t("a",g,[a[0]||(a[0]=n("辉煌头",-1)),o(r)])]),t("li",null,[t("a",u,[a[1]||(a[1]=n("辉煌衣",-1)),o(r)])]),t("li",null,[t("a",h,[a[2]||(a[2]=n("辉煌腿",-1)),o(r)]),a[3]||(a[3]=t("br",null,null,-1)),a[4]||(a[4]=n(" 无皇冠幣且算家园结界可以去打Spiral Cup Gauntlet(80等以上)，有Greenwarden’s Energetic套装，可以+61能量上限。",-1))])]),a[34]||(a[34]=t("h1",{id:"树根套",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#树根套","aria-hidden":"true"},"#"),n(" 树根套")],-1)),t("ul",null,[t("li",null,[t("a",m,[a[5]||(a[5]=n("树根头",-1)),o(r)])]),t("li",null,[t("a",b,[a[6]||(a[6]=n("树根衣",-1)),o(r)])]),t("li",null,[t("a",w,[a[7]||(a[7]=n("树根腿",-1)),o(r)]),a[8]||(a[8]=t("br",null,null,-1)),a[9]||(a[9]=n(" 无皇冠幣的法杖可以透过合成获得，完成奥创打造任务可以得到一个+11能量和5渔运的法杖",-1))])]),a[35]||(a[35]=p('<h2 id="植物的不同阶段" tabindex="-1"><a class="header-anchor" href="#植物的不同阶段" aria-hidden="true">#</a> <mark>植物的不同阶段</mark></h2><p>幼苗：植物的初期形态。不需要对植物使用特定的魔法，只需要等待它们进入成长期。</p><p>成长期：这时候的植物需要日常呵护，每种植物需要不同的照顾，水、阳光、音乐、授粉、魔法，以及可能会用到的驱虫</p><p>成熟期：成熟期的植物会开始掉落奖励，但除了极个别珍惜植物（例如超级欧芹）外，掉落物都比较普通。和成长阶段一样，这时候的植物同样需要日常呵护</p><p>老年期：年老的植物会发光，可以对其摁X进行收获，同时植物会掉落比较稀有的宝藏卡、材料和小吃。收获完后会返还一颗对应的植物种子</p><p>枯萎期：顾名思义，没有得到及时照顾的植物会慢慢枯萎。但是一旦满足了植物需求，它们会重新进入成长期。</p><p>死亡：植物死亡。如果想救活需要浪费30能量，得不偿失。</p><h2 id="如何播种-照顾植物" tabindex="-1"><a class="header-anchor" href="#如何播种-照顾植物" aria-hidden="true">#</a> <mark>如何播种&amp;照顾植物</mark></h2><p>在拥有农场后，你可以从Farley（魔法城wizard city-傀儡庭院golem court）那里购买到1级的初级种子，根据种子适应的地块来进行播种。Farley会给你四个基础魔法，但是每个植物的需求不同，所以在种植前需要了解植物的需求。鼠标移动到植物上即可看到。犁耕可以清除任意生长阶段的植物，常用来清除已死亡植物。</p><figure><img src="https://subata.top/wp-content/uploads/2023/07/Small-Soil-GARDENINGSPELL.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>↑顾名思义，只适合种植小型植物。中型和大型以此类推 完成最初任务后，你可以在任何时间和Farley交谈并学习更多园艺魔法。1级可以学的有暖阳，水雾，授粉，魔法之触，独奏和害虫防护-等级1。除了除虫法术以外，其他的需要3能量进行释放，同样请根据不同植物的不同需求来进行释放。具体需求会显示在已播种植物的正上方</p><figure><img src="https://subata.top/wp-content/uploads/2023/07/Warming-Rays-GARDENINGSPELL-1.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>↑照顾植物的魔法其中之一，可以根据植物的不同需求来学习不同的魔法。</p><h2 id="如何加速植物成长" tabindex="-1"><a class="header-anchor" href="#如何加速植物成长" aria-hidden="true">#</a> <mark>如何加速植物成长</mark></h2><p>每个植物会有喜欢的物品、植物、环境，当植物附近有这些东西时会增加植物的生长速度，快速到达老年期(又称大收成)。大部分的植物在大收成才会获得较好的奖励，所以请尽力凑齐这些条件。 反之，每个植物也有討厌的植物，反而会减慢植物的生长速度，要尽量避免这些植物在附近。 以下以couch potato(沙发土豆)的成长速度加成为例:</p><p>通常有固定几样物品每个植物都喜欢。</p><ol><li>第一是 Red Barn Farm，可以在皇冠幣商城用金幣购买这个房子。只要植物种在这个房子的屋內或屋外都可以吃到+15%的成长速度加成</li><li>第二是Tropical Garden Gnome(种植小矮人)，可以在魔法城-木偶村的土拨鼠轻易地买到。把种植小矮人放在植物附近，会有一定的范围內的植物获得+25%的成长速度加成。</li><li>第三是Pixie(精灵)，这个是附在植物上的状態，能靠10等在沙鱷-绿洲的土拨鼠学到的Summon Pixie附在植物上。<br> 在被附上精灵状態的植物附近会有一定的范围內让植物获得+20%的成长速度加成(含自己)。<br> 精灵算是一种长效保护类型的法术(这个之后会提)，只能持续一对时间，48小时后需要重新施放才能保持加成的状態。 但是能量宠中的种植宠会有maycast Summon Pixie的天赋。在你施放其他成长法术(太阳、下雨等)时，会有机率对法术的目標植物施放Summon Pixie，可以有效地节省能量。</li></ol><h2 id="植物种植推荐" tabindex="-1"><a class="header-anchor" href="#植物种植推荐" aria-hidden="true">#</a> <mark>植物种植推荐</mark></h2>',18)),t("ol",null,[t("li",null,[a[11]||(a[11]=n("粉色蒲公英(等级1可种)(小)(害虫1等)(蜜蜂、下雨) \\重点產物:黑珍珠、血苔、弹簧、古老卷轴。 优点:1等就可以种，而且种子还可以合成种子仓库，详见⁠游戏观念_合成篇。",-1)),a[12]||(a[12]=t("mark",null,"但是并不建议萌新种这个，最好留25个造种子仓库。更好的植物可以看下面的2.",-1)),a[13]||(a[13]=n(" \\取得管道:沙鱷的小怪和boss关，本人推荐打沙鱷- Palace of Fire 的Nebit Nirini刷，副產物是energy opal。",-1)),a[14]||(a[14]=t("br",null,null,-1)),t("a",f,[a[10]||(a[10]=n('点击这里前往"粉红蒲公英"wiki界面',-1)),o(r)])]),t("li",null,[a[16]||(a[16]=n("黄色灯笼椒(等级1可种)(小)(害虫一级)(太阳)",-1)),a[17]||(a[17]=t("br",null,null,-1)),a[18]||(a[18]=n(" 重点产物:无",-1)),a[19]||(a[19]=t("br",null,null,-1)),a[20]||(a[20]=n(" 优点:可以集市买，需求少，种三颗收完老年就能升到3级。",-1)),a[21]||(a[21]=t("br",null,null,-1)),a[22]||(a[22]=n(" 获取通道:集市买，扎法园艺大师购买",-1)),a[23]||(a[23]=t("br",null,null,-1)),t("a",c,[a[15]||(a[15]=n('点击这里前往"黄色灯笼椒"wiki界面',-1)),o(r)])]),t("li",null,[a[25]||(a[25]=n("动感香芹王(等级3可种)(中)(害虫1、2等)(太阳、音乐) \\重点產物:醚、琥珀、蓝晶、黑珍珠、钻石、弹簧、太阳石。 优点:成熟期收成有机会会给花椰菜种子，可以达到1生2的恐怖成长。並且是沙发马铃薯喜欢的植物。 取得管道:火龙谷的boss关。本人推荐打火龙谷-The Grand Chasm的Vasek Ashweaver，副產物是灵魂系学院的技能碎片。或是打火龙谷-The Crystal Grove的Chronius，副產物是元素系学院的技能碎片。",-1)),a[26]||(a[26]=t("br",null,null,-1)),t("a",k,[a[24]||(a[24]=n('点击这里前往"动感香芹王"wiki界面',-1)),o(r)])]),t("li",null,[a[28]||(a[28]=n("沙发土豆(等级3可种)(大)(害虫1等)(下雨、音乐)\\ 重点產物:9等零食、empower金卡(emp)。 优点:可以获得+50宠物经验的宠物点心，emp可以拿去拍卖卖掉或是与其他玩家进行游戏外交易。 取得管道:打天界-Aeriel Jungle – Monkey Spider Cave的Monkey Spider刷，副產物是10%金点宝石、攻击类型宠物天赋宝石。",-1)),a[29]||(a[29]=t("br",null,null,-1)),t("a",y,[a[27]||(a[27]=n('点击这里前往"沙发土豆"wiki界面',-1)),o(r)])])]),a[36]||(a[36]=t("h2",{id:"如何用最少的能量照顾到最多的植物",tabindex:"-1"},[t("a",{class:"header-anchor",href:"#如何用最少的能量照顾到最多的植物","aria-hidden":"true"},"#"),n(),t("mark",null,"如何用最少的能量照顾到最多的植物")],-1)),t("p",null,[a[31]||(a[31]=n("小型土壤推荐这样种(68格) (不会使用到任何的卡bug技巧) 中、大型土壤的种植教学可以参考B站零时搬运的69饼干田种植攻略 ",-1)),t("a",z,[a[30]||(a[30]=n("点击前往",-1)),o(r)]),a[32]||(a[32]=n(" 特別要注意的是，细微调整需要调整成绝对座標(要出现x、y、z轴)",-1))]),a[37]||(a[37]=p('<h2 id="如何快速升级" tabindex="-1"><a class="header-anchor" href="#如何快速升级" aria-hidden="true">#</a> <mark>如何快速升级</mark></h2><p>3等前: <br> 因为成长法术只能对单个植物生效，所以植物不要种太多(除非你能量很多)。种三颗集市可买的&quot;黄色灯笼椒&quot;来渡过前期。</p><p>3等到5等前: 去沙鱷找土拨鼠学到的新成长法术作用范围没有到最大，但是也能有效地节省能量(相比1等地成长法术)。可以开始种舞王。</p><p>5等后:<br> 去木须找土拨鼠学到的新成长法术作用范围是最大的。可以开始种马铃薯、碗豆。</p><p>10等:<br> 去阿瓦隆-Caliburn找Sumner Fieldgold接There’s the Shrub的支线任务，可以解锁阿瓦隆的土拨鼠。(前提主线进度需要解完Queen of Light took her Bow)</p><p>15等:<br> 去虫国-Bastion找Zaltanna the Mirrormask接Bring The Green的支线任务，可以解锁虫国的土拨鼠。(前提主线进度需要解完Uneasy Allies)</p><h2 id="_48小时保护魔法" tabindex="-1"><a class="header-anchor" href="#_48小时保护魔法" aria-hidden="true">#</a> <mark>48小时保护魔法</mark></h2><p>以防虫法术为例，两种法术的耗能不一样。 一般法术的优点是单次耗能少，但是过一阵子就还是会產生害虫。 长效保护法术虽然单次耗能多，但是可以持续一阵子，並且施放当下也可以驱虫。</p><p>以一天顾一次，共计三天: 一般法术需要花15点能量，但是长效保护法术只需花10点能量。 以总能量的消耗来看，长效保护法术能有效地节省能量。</p><figure><img src="https://media.discordapp.net/attachments/1068549367310594048/1068803125646987264/2023-01-28_154755.png?width=352&amp;height=251" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="如何获得园艺技能" tabindex="-1"><a class="header-anchor" href="#如何获得园艺技能" aria-hidden="true">#</a> <mark>如何获得园艺技能？</mark></h2><p>和常规战斗魔法不同，园艺技能并不需要训练点，而是需要大量金币并从鼹鼠Farley那里购买获得。目前共有45种不同的园艺技能，分布在不同世界的不同Farley身上。</p><p><strong>建议只选择自己需要的进行学习，因为学完所有技能的金币花费为2692100.</strong></p><h2 id="任务技能" tabindex="-1"><a class="header-anchor" href="#任务技能" aria-hidden="true">#</a> <mark>任务技能：</mark></h2><p>完成12级接取的初始园艺任务即可免费获得。</p><p><img src="https://subata.top/wp-content/uploads/2023/07/3BSPCK9MS2ESYR88TJZW7.png" alt="" width="150" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/A7DGVBNB4IMH23IU.png" alt="" width="150" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/GHHBJKCVBZ3LUCSD.png" alt="" width="150" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/YAIDE@4N9UKG8X5U5YND.png" alt="" width="150" loading="lazy"></p><h2 id="魔法城的鼹鼠老师" tabindex="-1"><a class="header-anchor" href="#魔法城的鼹鼠老师" aria-hidden="true">#</a> <mark>魔法城的鼹鼠老师</mark></h2><p>可以在傀儡庭院找到它</p><p><img src="https://subata.top/wp-content/uploads/2023/07/G4Q8KSJT730H37X.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/3ZQQY5R3J4H4UOK8PSS.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/TL8X2_949OUQLF47.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/HEYFZ3G8ZAX06CLP4.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/92R7JOAM0J3VQTIGY4.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/T2@OFHJQA7MUZ_A0YYEL.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/VVDTMVYQ0IN3TFMT4Q200.png" alt="" loading="lazy"></p><h2 id="克罗克的鼹鼠老师" tabindex="-1"><a class="header-anchor" href="#克罗克的鼹鼠老师" aria-hidden="true">#</a> <mark>克罗克的鼹鼠老师</mark></h2><p>绿洲靠近金字塔的位置可以找到它，可以学到中范围魔法以及大片土壤开垦魔法</p><p><img src="https://subata.top/wp-content/uploads/2023/07/XF4XA2TA3PNYSAPJTIM4LC5.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/2E3TDXS23W@OGOXCX.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/NIYOI@THPA50EAJFL.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/372BQCMN772K7UPXLF.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/UCIZNE_P3DKGYYLGX4R.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/J@C7S_12O_K0ESL8.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/OFN6HLVFRIRZIJ3CY6Y.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/L2IG4UUKJR52@1WIJGUF.png" alt="" loading="lazy"></p><h2 id="木须的鼹鼠老师" tabindex="-1"><a class="header-anchor" href="#木须的鼹鼠老师" aria-hidden="true">#</a> <mark>木须的鼹鼠老师</mark></h2><p>走出旋涡门所在的房间，可以在翡翠殿找到它。可以学到大范围魔法</p><p><img src="https://subata.top/wp-content/uploads/2023/07/LITTBQ7_2TV6QIK0AHY4.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/@3EHLI3SHOW7MD6ZY6M.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/7D9KY34CTTL0MMBKQPXA7.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/T21PTGAKWQVP@OWOEMX.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/6DZ3RZH@IU5RZCAR4_L.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/M7L18C6KBEWGL957YEYCG.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/KZBNHMIM@E9H31W03.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/LIZ25LVM1T6TM41AYBNC.png" alt="" loading="lazy"></p><h2 id="天国的鼹鼠老师" tabindex="-1"><a class="header-anchor" href="#天国的鼹鼠老师" aria-hidden="true">#</a> <mark>天国的鼹鼠老师</mark></h2><p>在天国的大本营可以找到它，提供一个特别有用的48小时除虫魔法</p><figure><img src="https://subata.top/wp-content/uploads/2023/07/U@JHEHPIW6V4ZWK5O3X.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><h2 id="扎法丛林的鼹鼠老师" tabindex="-1"><a class="header-anchor" href="#扎法丛林的鼹鼠老师" aria-hidden="true">#</a> <mark>扎法丛林的鼹鼠老师</mark></h2><p>可以在大草原的入口找到它。提供两个48小时高级除虫魔法</p><figure><img src="https://subata.top/wp-content/uploads/2023/07/GXZ3Y7HW8V80QK337CPL-1024x920.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><img src="https://subata.top/wp-content/uploads/2023/07/IN7TE2OE17KBVO.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/72CCXENN8HCUYE2LFHLT8.png" alt="" loading="lazy"></p><h2 id="阿瓦隆的鼹鼠老师" tabindex="-1"><a class="header-anchor" href="#阿瓦隆的鼹鼠老师" aria-hidden="true">#</a> <mark>阿瓦隆的鼹鼠老师</mark></h2><p>需要到达园艺等级10级，并完成主线任务“Queen of Light took her Bow”以及支线任务 “There’s the Shrub”才能进行学习。可以学到一键种植魔法一劳永逸</p><figure><img src="https://subata.top/wp-content/uploads/2023/07/1MG0RR8WS81UQ2F8RGE.png" alt="↑接取任务地点" tabindex="0" loading="lazy"><figcaption>↑接取任务地点</figcaption></figure><p><img src="https://subata.top/wp-content/uploads/2023/07/QKM_Q8FY9_271Q4J@_2X.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/NG3TOJ973JE4TD_SAJZ2.png" alt="" loading="lazy"></p><figure><img src="https://subata.top/wp-content/uploads/2023/07/QPBR55J1P4QSZRUACTV3.png" alt="↑↑重点注意，由于没有二次确定很容易手滑，不推荐萌新学这个全部犁，会一键铲除所有土壤" tabindex="0" loading="lazy"><figcaption>↑↑重点注意，由于没有二次确定很容易手滑，不推荐萌新学这个全部犁，会一键铲除所有土壤</figcaption></figure><p><img src="https://subata.top/wp-content/uploads/2023/07/4H91VMGH7MC0J57S9QG6F.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/QY@1@U26GFNUPR0UKSPI.png" alt="" loading="lazy"></p><h2 id="虫国的鼹鼠老师" tabindex="-1"><a class="header-anchor" href="#虫国的鼹鼠老师" aria-hidden="true">#</a> <mark>虫国的鼹鼠老师</mark></h2><p>需要达到园艺等级15级，完成整个支线“Bring the Green”才能进行学习。虫国主城左手边的螳螂镜子面具Zaltanna可以接取。提供特别有用的48小时呵护植物魔法</p><figure><img src="https://subata.top/wp-content/uploads/2023/07/A@0NAOR61F5F2BA@P41O.png" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p><img src="https://subata.top/wp-content/uploads/2023/07/JO5N2QDRFCH7W4BEI_1F.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/8SC9HB8BFNWIV3642TXD8.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/ZGBG6PRZLPN3WAY8JP.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/ZGBG6PRZLPN3WAY8JP.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/DXPJO@SL0HZ8HF47TH6.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/@399_AO1SAHN9RO.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/K4O8BIKN@EHJDCBP.png" alt="" loading="lazy"><img src="https://subata.top/wp-content/uploads/2023/07/GMH35J48VXURSYK80U8.png" alt="" loading="lazy"></p><p>以上就是所有可以习得的种植魔法，祝各位小魔法师早日实现小吃/琥珀/珍惜宝藏卡自由！</p><h2 id="前期如何获得-沙发土豆" tabindex="-1"><a class="header-anchor" href="#前期如何获得-沙发土豆" aria-hidden="true">#</a> <mark>前期如何获得&quot;沙发土豆&quot;</mark></h2><ol><li>在解锁完&quot;格林海姆&quot;后,在&quot;萨塔瓦斯塔德通道&quot;找到&quot;混乱的战士&quot;不断Farming刷刷刷就可以拿到沙发土豆种子,但是爆率较低。所以并不推荐萌新前期把时间浪费在这里，但也是为想刷取的萌新提供这一种办法。</li><li>找&quot;我是马猪是魔法装饰师(QQ:2726632635)&quot;购买刷取土豆服务,20元=69个土豆种子=一片田 甚至有时候更多。</li></ol>',45))])}const P=i(d,[["render",x],["__file","index2.html.vue"]]);export{P as default};
